700	+/// SMA-730: the upstream ended or failed. A last record with no blank line after it still
701	+/// counts. Without a guard the scanner reads nothing, as in the chunk arm. Shared with the
702	+/// intercepting relay (SMA-749 D24).
703	+pub(crate) fn finish_scan(scan: &mut StreamUsage, guard: &mut Option<ChargeGuard>) {
704	+    if let Some(guard) = guard.as_mut() {
705	+        scan.finish();
706	+        guard.set_stream_progress(scan.completion_records(), scan.reported_total());
707	+    }
708	+}
709	+
710	+/// Adapt an [`OpenAiByteStream`] into a body stream that forwards each upstream chunk UNBUFFERED
711	+/// and, on the FIRST upstream error, emits one `terminal` event and ends.
712	+///
713	+/// Items are `Result<Bytes, Infallible>`: the outgoing stream never errors (a mid-stream upstream
714	+/// failure becomes a data event, not a transport error), which keeps `Body::from_stream` from
715	+/// aborting the response body. The inner stream is owned by the unfold state and dropped when this
716	+/// stream is dropped — preserving reqwest's cancel-on-drop of the upstream request.
717	+///
718	+/// Runs with `paigasus_observability::current_ids() == None` (SMA-504 spec §4.3, situation 3):
719	+/// this function is polled by hyper after the request-head future — the one the
720	+/// `CorrelationLayer` task-local scope covers — has already resolved. See the call site's
721	+/// comment in [`pipeline::proxy`](super::pipeline::proxy).
722	+pub(crate) fn terminal_sse_error_stream(
723	+    inner: OpenAiByteStream,
724	+    guard: Option<ChargeGuard>,
725	+    usage: StreamUsage,
726	+    terminal: &'static str,
727	+) -> impl Stream<Item = Result<Bytes, Infallible>> + Send + 'static {
728	+    let start = Relay {
729	+        phase: StreamState::Streaming(inner),
730	+        scan: usage,
731	+        guard,
732	+    };
733	+    futures::stream::unfold(start, move |Relay { phase, mut scan, mut guard }| async move {
734	+        match phase {
735	+            StreamState::Streaming(mut inner) => match inner.next().await {
736	+                // Forward each chunk exactly as it arrived (unbuffered). The scanner reads a copy,
737	+                // and only when a guard exists (no `[limits]`: no parsing at all).
738	+                Some(Ok(chunk)) => {
739	+                    feed_scan(&mut scan, &mut guard, &chunk);
740	+                    Some((
741	+                        Ok(chunk),
742	+                        Relay {
743	+                            phase: StreamState::Streaming(inner),
744	+                            scan,
745	+                            guard,
746	+                        },
747	+                    ))
748	+                }
749	+                // First upstream error: count the last record (the frame's leading blank line
750	+                // closes it for the client too), emit the terminal event, then end.
751	+                Some(Err(_)) => {
752	+                    finish_scan(&mut scan, &mut guard);
753	+                    Some((
754	+                        Ok(Bytes::from_static(terminal.as_bytes())),
755	+                        Relay {
756	+                            phase: StreamState::Done,
757	+                            scan,
758	+                            guard,
759	+                        },
760	+                    ))
761	+                }
762	+                // Clean upstream end: count the last record, then drop the relay and the guard.
763	+                None => {
764	+                    finish_scan(&mut scan, &mut guard);
765	+                    None
766	+                }
767	+            },
768	+            StreamState::Done => None,
769	+        }
770	+    })
771	+}
