846	+/// D15: the interception limits with the record and hold caps of `[responses]`. The route is
847	+/// mounted only when `state.responses` is `Some`, so the fallback to the shared limits is not
848	+/// reached.
849	+fn responses_limits(ti: &ToolInterception, state: &AppState) -> Limits {
850	+    match &state.responses {
851	+        Some(settings) => Limits {
852	+            max_record_bytes: settings.max_record_bytes,
853	+            max_held_bytes: settings.max_held_bytes,
