859	+
860	+/// Parse a COPY of the body (§ 7.2). The failure split is that of chat (SMA-588): a body that
861	+/// cannot be read is `BadRequestBody`; a body that is JSON but not the request shape (not an
862	+/// object, a field of the wrong type, an `input` that is not a string or an array) is
863	+/// `InvalidRequestSchema`. Then D4 and D3, in the order of [`refuse_stateful`].
864	+fn parse_responses(body: &[u8], interception: bool) -> Result<RequestFacts, GatewayError> {
865	+    let value: Value = serde_json::from_slice(body).map_err(|e| match e.classify() {
866	+        serde_json::error::Category::Data => GatewayError::InvalidRequestSchema,
867	+        serde_json::error::Category::Syntax | serde_json::error::Category::Eof | serde_json::error::Category::Io => GatewayError::BadRequestBody,
868	+    })?;
869	+    let dto = ResponsesRequest::deserialize(&value).map_err(|_| GatewayError::InvalidRequestSchema)?;
870	+    if !matches!(dto.input, None | Some(Value::String(_) | Value::Array(_))) {
871	+        return Err(GatewayError::InvalidRequestSchema);
872	+    }
873	+    refuse_stateful(&dto, interception)?;
874	+    Ok(RequestFacts {
875	+        request_estimate: responses_usage::request_tokens_estimate(&value, body.len()),
876	+        model: dto.model.unwrap_or_else(|| "-".to_owned()),
877	+        stream: dto.stream.unwrap_or(false),
878	+    })
879	+}
880	+
881	+/// D4 always, then D3 when interception is on, in the order `background`,
882	+/// `previous_response_id`, `conversation`, `prompt`, `input`. The first match names its `param`.
883	+fn refuse_stateful(dto: &ResponsesRequest, interception: bool) -> Result<(), GatewayError> {
884	+    let refuse = |param| Err(GatewayError::ResponsesStatefulNotSupported { param });
885	+    if dto.background == Some(true) {
886	+        return refuse("background");
887	+    }
888	+    if !interception {
889	+        return Ok(());
890	+    }
891	+    if dto.previous_response_id.is_some() {
892	+        return refuse("previous_response_id");
893	+    }
894	+    if dto.conversation.is_some() {
895	+        return refuse("conversation");
896	+    }
897	+    if dto.prompt.is_some() {
898	+        return refuse("prompt");
899	+    }
900	+    if let Some(Value::Array(items)) = &dto.input
901	+        && items.iter().any(is_item_reference)
902	+    {
903	+        return refuse("input");
904	+    }
905	+    Ok(())
906	+}
