1101	+/// Blocks every call whose name starts with `blocked_`.
1102	+struct BlockNamed;
1103	+
1104	+impl ToolCallDecider for BlockNamed {
1105	+    fn decide(&self, _ctx: Arc<DecisionContext>, _turn: Arc<ToolTurn>, calls: Vec<ToolCall>) -> DecideFuture {
1106	+        let d = calls
1107	+            .iter()
1108	+            .map(|c| {
