1229	+fn blocked_stream(total: u64, pad: usize) -> Vec<String> {
1230	+    let mut e = Events::created();
1231	+    let a = e.function_call(0, "read_file", "{\"p\":1}");
1232	+    let b = e.function_call(1, "blocked_rm", "{\"path\":\"CANARY\"}");
1233	+    e.completed(vec![a, b], total, pad)
1234	+}
