881	+/// D4 always, then D3 when interception is on, in the order `background`,
882	+/// `previous_response_id`, `conversation`, `prompt`, `input`. The first match names its `param`.
883	+fn refuse_stateful(dto: &ResponsesRequest, interception: bool) -> Result<(), GatewayError> {
884	+    let refuse = |param| Err(GatewayError::ResponsesStatefulNotSupported { param });
885	+    if dto.background == Some(true) {
886	+        return refuse("background");
887	+    }
888	+    if !interception {
889	+        return Ok(());
890	+    }
891	+    if dto.previous_response_id.is_some() {
892	+        return refuse("previous_response_id");
893	+    }
894	+    if dto.conversation.is_some() {
895	+        return refuse("conversation");
896	+    }
897	+    if dto.prompt.is_some() {
898	+        return refuse("prompt");
899	+    }
900	+    if let Some(Value::Array(items)) = &dto.input
901	+        && items.iter().any(is_item_reference)
902	+    {
903	+        return refuse("input");
904	+    }
905	+    Ok(())
906	+}
