908	+/// An `item_reference` input item. Its `type` is optional in the API (openai-python 3.48.0
909	+/// `ItemReference`: `id` required, `type` `Optional[Literal["item_reference"]]`), so an item with
910	+/// no `type` (or a `null` one) and no `role` is a reference too. The only other untyped item, the
911	+/// easy input message, always has a `role`.
912	+fn is_item_reference(item: &Value) -> bool {
913	+    let Some(obj) = item.as_object() else { return false };
914	+    match obj.get("type") {
915	+        Some(Value::String(ty)) => ty == "item_reference",
916	+        None | Some(Value::Null) => !obj.contains_key("role"),
917	+        Some(_) => false,
918	+    }
919	+}
