1202	+        e.push(json!({"type":"response.in_progress","response":response}));
1203	+        e
1204	+    }
1205	+
1206	+    /// One `function_call` item at `index`, with one argument delta. Returns the done item.
1207	+    fn function_call(&mut self, index: u32, name: &str, args: &str) -> Value {
1208	+        let (id, call_id) = (format!("fc_{index}"), format!("call_{index}"));
1209	+        let added = json!({"type":"function_call","id":id,"status":"in_progress","call_id":call_id,"name":name,"arguments":""});
1210	+        self.push(json!({"type":"response.output_item.added","item":added,"output_index":index}));
1211	+        self.push(json!({"type":"response.function_call_arguments.delta","delta":args,"item_id":id,"output_index":index}));
1212	+        self.push(json!({"type":"response.function_call_arguments.done","arguments":args,"item_id":id,"output_index":index}));
1213	+        let done = json!({"type":"function_call","id":id,"status":"completed","call_id":call_id,"name":name,"arguments":args});
1214	+        self.push(json!({"type":"response.output_item.done","item":done,"output_index":index}));
1215	+        done
1216	+    }
1217	+
1218	+    /// The terminal event, with `pad` bytes of `instructions` to make it large.
1219	+    fn completed(mut self, output: Vec<Value>, total: u64, pad: usize) -> Vec<String> {
1220	+        let response = json!({"id":"resp_1","object":"response","status":"completed","instructions":"x".repeat(pad),"output":output,
1221	+            "usage":{"input_tokens":3,"output_tokens":5,"total_tokens":total}});
1222	+        self.push(json!({"type":"response.completed","response":response}));
1223	+        self.out
1224	+    }
1225	+}
